import { MakeLogicType, actions, afterMount, connect, kea, listeners, path, reducers, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import { projectLogic } from 'scenes/projectLogic'

import { flagRequestsVolumeRetrieve } from '../generated/api'
import {
    type FlagRequestMetricsResponseApi,
    FlagRequestsVolumeRetrieveBreakdown,
    FlagRequestsVolumeRetrieveInterval,
} from '../generated/api.schemas'

export interface FlagRequestVolumeTotal {
    name: string
    requests: number
    billableRequests: number
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface flagRequestVolumeLogicValues {
    currentProjectId: number | null // projectLogic
    breakdown: FlagRequestsVolumeRetrieveBreakdown
    dateFrom: string
    dateTo: string
    interval: FlagRequestsVolumeRetrieveInterval
    requestVolume: FlagRequestMetricsResponseApi | null
    requestVolumeLoading: boolean
    totals: FlagRequestVolumeTotal[]
    hasRequests: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface flagRequestVolumeLogicActions {
    setBreakdown: (breakdown: FlagRequestsVolumeRetrieveBreakdown) => { breakdown: FlagRequestsVolumeRetrieveBreakdown }
    setDates: (dateFrom: string, dateTo: string) => { dateFrom: string; dateTo: string }
    loadRequestVolume: () => any
    loadRequestVolumeFailure: (error: string, errorObject?: any) => { error: string; errorObject?: any }
    loadRequestVolumeSuccess: (
        requestVolume: FlagRequestMetricsResponseApi | null,
        payload?: any
    ) => { requestVolume: FlagRequestMetricsResponseApi | null; payload?: any }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface flagRequestVolumeLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        interval: (dateFrom: string) => FlagRequestsVolumeRetrieveInterval
        totals: (requestVolume: FlagRequestMetricsResponseApi | null) => FlagRequestVolumeTotal[]
        hasRequests: (totals: FlagRequestVolumeTotal[]) => boolean
    }
}

export type flagRequestVolumeLogicType = MakeLogicType<
    flagRequestVolumeLogicValues,
    flagRequestVolumeLogicActions,
    Record<string, any>,
    flagRequestVolumeLogicMeta
>

export const flagRequestVolumeLogic = kea<flagRequestVolumeLogicType>([
    path(['products', 'feature_flags', 'frontend', 'requestVolume', 'flagRequestVolumeLogic']),
    connect(() => ({
        values: [projectLogic, ['currentProjectId']],
    })),
    actions({
        setBreakdown: (breakdown: FlagRequestsVolumeRetrieveBreakdown) => ({ breakdown }),
        setDates: (dateFrom: string, dateTo: string) => ({ dateFrom, dateTo }),
    }),
    reducers({
        breakdown: [
            FlagRequestsVolumeRetrieveBreakdown.RequestType as FlagRequestsVolumeRetrieveBreakdown,
            { setBreakdown: (_, { breakdown }) => breakdown },
        ],
        dateFrom: ['-7d', { setDates: (_, { dateFrom }) => dateFrom }],
        dateTo: ['-0d', { setDates: (_, { dateTo }) => dateTo }],
    }),
    loaders(({ values }) => ({
        requestVolume: [
            null as FlagRequestMetricsResponseApi | null,
            {
                loadRequestVolume: async () => {
                    if (values.currentProjectId === null) {
                        return null
                    }
                    return await flagRequestsVolumeRetrieve(String(values.currentProjectId), {
                        after: values.dateFrom,
                        before: values.dateTo,
                        breakdown: values.breakdown,
                        interval: values.interval,
                    })
                },
            },
        ],
    })),
    selectors({
        interval: [
            (s) => [s.dateFrom],
            // A single day of daily buckets is one bar, so short ranges are shown by the hour.
            (dateFrom): FlagRequestsVolumeRetrieveInterval =>
                dateFrom === '-24h' || dateFrom === '-1d'
                    ? FlagRequestsVolumeRetrieveInterval.Hour
                    : FlagRequestsVolumeRetrieveInterval.Day,
        ],
        totals: [
            (s) => [s.requestVolume],
            (requestVolume): FlagRequestVolumeTotal[] => {
                if (!requestVolume) {
                    return []
                }
                return requestVolume.series
                    .map((series) => {
                        const requests = series.values.reduce((sum, value) => sum + value, 0)
                        // A series named after an SDK has no billing weight of its own, so it falls back
                        // to 1 and the billable column matches the request count.
                        const weight = requestVolume.billing_weights[series.name] ?? 1
                        return { name: series.name, requests, billableRequests: requests * weight }
                    })
                    .filter((total) => total.requests > 0)
                    .sort((a, b) => b.requests - a.requests)
            },
        ],
        hasRequests: [(s) => [s.totals], (totals): boolean => totals.length > 0],
    }),
    listeners(({ actions }) => ({
        setBreakdown: () => actions.loadRequestVolume(),
        setDates: () => actions.loadRequestVolume(),
    })),
    afterMount(({ actions }) => {
        actions.loadRequestVolume()
    }),
])
